<?php require '_menu.php'; require_perm('users');
if ($_SERVER['REQUEST_METHOD'] === 'POST') { csrf_check();
    if (isset($_POST['toggle'])) { q('UPDATE users SET active=1-active WHERE id=? AND role<>\'admin\'', [(int)$_POST['toggle']]); audit('account_toggled', $_POST['toggle']); flash('Account updated.'); }
    elseif (isset($_POST['reset'])) { q('UPDATE users SET must_change=1, password_hash=? WHERE id=? AND role<>\'admin\'', [password_hash('Password@123', PASSWORD_DEFAULT), (int)$_POST['reset']]); audit('password_reset', $_POST['reset']); flash('Password reset to Password@123. Ask the user to change it after login.'); }
    elseif (isset($_POST['setkids'])) { $pid = (int)$_POST['setkids']; $n = link_children($pid, $_POST['children'][$pid] ?? ''); audit('children_linked', "parent $pid: $n child(ren)"); flash("This parent is now linked to $n child(ren)."); }
    else { $f = array_map('trim', $_POST);
        if (!$f['full_name'] || !$f['username'] || strlen($f['password']) < 6 || !in_array($f['role'], ['teacher', 'student', 'principal', 'hr', 'parent'], true)) flash('Fill in name, username, role and a password of at least 6 characters.', 'err');
        elseif (q('SELECT 1 FROM users WHERE username=?', [$f['username']])->fetch()) flash('That username is taken.', 'err');
        else { q('INSERT INTO users (role,full_name,username,email,class_name,password_hash,must_change) VALUES (?,?,?,?,?,?,1)', [$f['role'], $f['full_name'], $f['username'], $f['email'], $f['class_name'], password_hash($f['password'], PASSWORD_DEFAULT)]); $pid = (int)db()->lastInsertId(); $kids = $f['role'] === 'parent' ? link_children($pid, $f['children'] ?? '') : 0; audit('account_created', $f['username'] . ' (' . $f['role'] . ')'); flash('Account created. The user must choose a new password at first login.' . ($f['role'] === 'parent' ? " Linked $kids child(ren)." : '')); } }
    go('admin/users.php'); }
$r = $_GET['r'] ?? ''; $rows = in_array($r, ['teacher', 'student', 'principal', 'hr', 'parent'], true) ? q("SELECT * FROM users WHERE role=? ORDER BY class_name, full_name", [$r])->fetchAll() : q("SELECT * FROM users WHERE role<>'admin' ORDER BY role, class_name, full_name")->fetchAll();
$kids = q("SELECT pc.parent_id, GROUP_CONCAT(u.full_name SEPARATOR ', ') FROM parent_children pc JOIN users u ON u.id=pc.student_id GROUP BY pc.parent_id")->fetchAll(PDO::FETCH_KEY_PAIR);
app_top('Accounts & roles', $menu, $area); ?>
<h1>Accounts & roles</h1><p class="mini">Admin: everything. Principal: grades, report cards, students, exam timetable, notices, applications. HR / Accountant: staff records, payroll, leave. Teachers, students and parents use the e-portal, from the same login page as everyone else. A parent sees only the children linked to their account.</p>
<form method="post" class="panel f" style="max-width:none"><?= csrf_field() ?><h3>Create an account</h3>
<div class="row"><div><label>Full name</label><input name="full_name" required></div><div><label>Role</label><select name="role"><option value="student">Student</option><option value="teacher">Teacher</option><option value="principal">Principal</option><option value="hr">HR / Accountant</option><option value="parent">Parent</option></select></div></div>
<div class="row"><div><label>Username (used to log in)</label><input name="username" required></div><div><label>Temporary password</label><input name="password" required minlength="6"></div></div>
<div class="row"><div><label>Class (students only, e.g. JSS 1)</label><input name="class_name"></div><div><label>Email (optional)</label><input type="email" name="email"></div></div>
<div><label>Children's usernames (parents only, separated by commas)</label><input name="children" placeholder="e.g. student1, student2"></div>
<div><button class="btn">Create account</button></div></form>
<div class="chips"><a href="users.php" class="<?= $r ? '' : 'on' ?>">Everyone</a><a href="users.php?r=teacher" class="<?= $r === 'teacher' ? 'on' : '' ?>">Teachers</a><a href="users.php?r=student" class="<?= $r === 'student' ? 'on' : '' ?>">Students</a><a href="users.php?r=principal" class="<?= $r === 'principal' ? 'on' : '' ?>">Principal</a><a href="users.php?r=hr" class="<?= $r === 'hr' ? 'on' : '' ?>">HR</a><a href="users.php?r=parent" class="<?= $r === 'parent' ? 'on' : '' ?>">Parents</a></div>
<div class="tw"><table><thead><tr><th>Name</th><th>Username</th><th>Role</th><th>Class / children</th><th>Status</th><th></th></tr></thead><tbody>
<?php foreach ($rows as $x): ?><tr><td><?= e($x['full_name']) ?></td><td><?= e($x['username']) ?></td><td><?= e(ucfirst($x['role'])) ?></td><td><?= $x['role'] === 'parent' ? e($kids[$x['id']] ?? 'No child linked') : e($x['class_name']) ?></td><td><?= $x['active'] ? 'Active' : 'Disabled' ?></td>
<td><form method="post" class="acts"><?= csrf_field() ?><button class="btn small ghost" name="toggle" value="<?= $x['id'] ?>"><?= $x['active'] ? 'Disable' : 'Enable' ?></button><button class="btn small ghost" name="reset" value="<?= $x['id'] ?>" onclick="return confirm('Reset this password to Password@123?')">Reset password</button></form><?php if ($x['role'] === 'parent'): ?><form method="post" class="acts" style="margin-top:6px"><?= csrf_field() ?><input name="children[<?= $x['id'] ?>]" placeholder="student usernames" style="width:190px"><button class="btn small ghost" name="setkids" value="<?= $x['id'] ?>">Set children</button></form><?php endif; ?></td></tr>
<?php endforeach; if (!$rows) echo '<tr><td colspan="6">No accounts yet.</td></tr>'; ?></tbody></table></div>
<?php app_bottom();
